function a_tier_opts(bool $leer = true): array { $o = $leer ? ['' => 'keine'] : []; foreach (LD_TIERS as $t => $p) $o[$t] = $t . ' (' . ($p ? $p . ' €' : 'nach Absprache') . ')'; return $o; }
function a_kunde_name(array $k): string { return $k['firma'] !== '' ? $k['firma'] . ' (' . $k['name'] . ')' : ($k['name'] !== '' ? $k['name'] : $k['email']); }
function a_sel(string $name, array $opts, string $cur, string $attr = ''): string { $o = '<select name="' . $name . '" ' . $attr . '>'; foreach ($opts as $k => $v) $o .= '<option value="' . h((string)$k) . '"' . ((string)$k === $cur ? ' selected' : '') . '>' . h($v) . '</option>'; return $o . '</select>'; }
function a_konto_anlegen(string $email, string $name, string $firma, string $telefon, string $website, string $stufe, string $zahlung): array {
  /* Konto mit Startpasswort anlegen und Willkommens-Mail schicken. Gibt [kunde_id, fehler] zurück. */
  $email = strtolower(trim($email));
  if (!filter_var($email, FILTER_VALIDATE_EMAIL)) return [0, 'E-Mail ungültig.'];
  if (pd_row('SELECT 1 FROM kunden WHERE email = ?', [$email])) return [0, 'Zu dieser E-Mail gibt es schon ein Konto.'];
  $pw = ld_passwort_neu();
  $host = $website !== '' && ld_norm_url($website) ? ld_norm_url($website)['host'] : '';
  pd_q('INSERT INTO kunden (email, name, firma, telefon, website, rolle, pass_hash, pass_wechsel, stufe, zahlung, betreuung_seit, minuten_monat, angelegt) VALUES (?, ?, ?, ?, ?, ?, ?, 1, ?, ?, ?, ?, ?)',
    [$email, $name, $firma, $telefon, $host, 'kunde', password_hash($pw, PASSWORD_DEFAULT), $stufe, $zahlung, $stufe !== '' ? date('Y-m-d') : '', date('Y-m'), pd_now()]);
  $id = (int)pd()->lastInsertId();
  ld_empfehlungscode($id);
  pd_q('UPDATE auftraege SET kunde_id = ? WHERE kunde_id = 0 AND email = ?', [$id, $email]);
  $k = pd_row('SELECT * FROM kunden WHERE id = ?', [$id]);
  $ok = p_mail($k, 'Ihr Zugang zum Lou Digital Kundenportal', '<p style="margin:0">Guten Tag ' . h($name) . ',</p><p style="margin:10px 0 0">schön, dass wir zusammenarbeiten. Im Kundenportal sehen Sie jederzeit den Stand Ihres Projekts, Ihre Website, Ihre Automatik, Dokumente und Nachrichten. Melden Sie sich mit dem Startpasswort an und ersetzen Sie es direkt durch ein eigenes.</p>',
    ['Adresse' => LD_SITE . P_BASE, 'E-Mail' => $email, 'Startpasswort' => $pw], p_btn_link(LD_SITE . P_BASE . '/login', 'Zum Kundenportal') . '<p style="margin:14px 0 0;color:#4b585a;font-size:13px">Tipp: Unter „Einstellungen“ können Sie freiwillig einen zweiten Faktor (Authenticator-App) einschalten.</p>');
  pd_log($id, 'konto_neu', 'angelegt durch Büro');
  try { ld_buero_kunde_sync($k, 'kunde'); } catch (Throwable $e) {}
  return [$id, $ok ? '' : 'Konto angelegt, aber die Mail konnte nicht gesendet werden. Startpasswort: ' . $pw];
}

