case 'einstellungen':
  if ($post) {
    $url = trim(ld_post('bot_url', 300)); $burl = trim(ld_post('buero_url', 300)); $re = '~^https://n8n\.oblivion-hq\.duckdns\.org/webhook/[A-Za-z0-9_/-]+$~';
    if (($url !== '' && !preg_match($re, $url)) || ($burl !== '' && !preg_match($re, $burl))) p_flash('Nur Webhook-Adressen der eigenen n8n-Instanz.', 'warn');
    else { pd_set('bot_url', $url); pd_set('buero_url', $burl); p_flash('Gespeichert.' . ($burl !== '' ? (ld_buero('liste') ? ' Büro-Verbindung geprüft: OK.' : ' Büro-Verbindung antwortet nicht – Adresse prüfen.') : '')); }
    p_go(P_BASE . '/admin/einstellungen');
  }
  $dbf = ld_dir('ld-data') . '/portal.sqlite';
  out('Einstellungen', '<h1 class="p-h1">Einstellungen</h1><section class="p-card"><h2>Support-Bot</h2><p class="p-small p-muted">n8n-Webhook, der die Frage des Kunden mit Kontext bekommt (POST, JSON: quelle, frage, verlauf, kontext) und JSON mit <code>antwort</code> zurückgibt. Leer = feste Antworten aus Regeln.</p><form method="post" class="p-form p-form--wide">' . p_form($csrf) . '<label>Webhook-Adresse Hilfe-Assistent + Telegram (LD-09)<input name="bot_url" maxlength="300" value="' . h(pd_get('bot_url')) . '" placeholder="https://n8n.oblivion-hq.duckdns.org/webhook/…"></label><label>Webhook-Adresse Büro-Brücke (LD-10, Kunden/Eingang/Einsätze)<input name="buero_url" maxlength="300" value="' . h(pd_get('buero_url')) . '" placeholder="https://n8n.oblivion-hq.duckdns.org/webhook/…"></label><button class="btn btn--primary btn--small" type="submit">Speichern</button></form></section>'
    . '<section class="p-card"><h2>Technik</h2><dl class="p-dl"><dt>Datenbank</dt><dd><code>' . h($dbf) . '</code> (' . (is_file($dbf) ? number_format(filesize($dbf) / 1024, 0, ',', '.') . ' KB' : 'fehlt') . ')</dd><dt>Dokumente</dt><dd><code>' . h(ld_dir('ld-data') . '/portal-dokumente/') . '</code></dd><dt>Prüfung alle 5 Minuten</dt><dd><code>GET ' . LD_SITE . '/api/portal_cron.php</code> (prüft alle Kunden-Websites, höchstens alle 4 Minuten)</dd><dt>Sicherung</dt><dd>ld-data liegt außerhalb des Webroots; in die Plesk-Sicherung einbeziehen.</dd></dl></section>');

default:
  http_response_code(404);
  out('Nicht gefunden', '<section class="p-card"><h1>Seite nicht gefunden</h1><p><a href="' . P_BASE . '/admin">Zum Büro</a></p></section>');
}
